#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int EDAT;
    int CT = 0, SUM = 0, Q50 = 0;
    int ME = 0, QME = 0;

    cin >> EDAT;                      // lectura adelantada
    while (EDAT != 0) {
        CT++;                         // contador
        SUM = SUM + EDAT;             // acumulador
        if (EDAT >= 50) {
            Q50++;                    // contador con condición
        }
        if (EDAT > ME) {              // nuevo máximo
            ME = EDAT;
            QME = 1;
        } else if (EDAT == ME) {      // se repite el máximo
            QME++;
        }
        cin >> EDAT;                  // el siguiente, al final del cuerpo
    }

    double MIT = (double) SUM / CT;   // división real
    cout << fixed << setprecision(2);
    cout << "La mitjana d'edat es " << MIT << endl;
    cout << "Persones mes grans o iguals a 50 anys " << Q50 << endl;
    cout << "L'edat del mes gran es " << ME << endl;
    cout << "L'han tingut " << QME << " persones" << endl;
    return 0;
}

